import{_ as t,a,a3 as i,o as s}from"./chunks/framework.yJBLK5ap.js";const p=JSON.parse('{"title":"Chainguard Builds","description":"","frontmatter":{},"headers":[],"relativePath":"dockerfiles/chainguard/README.md","filePath":"dockerfiles/chainguard/README.md","lastUpdated":1795797312000}'),d={name:"dockerfiles/chainguard/README.md"};function n(r,e,o,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="chainguard-builds" tabindex="-1">Chainguard Builds <a class="header-anchor" href="#chainguard-builds" aria-label="Permalink to &quot;Chainguard Builds&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>From the HPCC-Platform repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/build.sh</span></span></code></pre></div><p>This builds HPCC Platform and creates APK, DEB, RPM, and SBOM files using <strong>glibc 2.34 and GCC 11</strong>. Build files and packages go in:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>build/chainguard-hpcc-glibc2.34-gcc11-amd64/</span></span></code></pre></div><p>No LN checkout is required.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Use Docker or Podman with a running engine. macOS also supports Apple&#39;s <code>container</code> CLI; Windows supports Docker, Podman, or WSL containers (<code>wslc.exe</code>) from Git Bash.</p><p>The scripts automatically select the first usable runtime, trying Docker before Podman. An installed Docker CLI without a running engine does not prevent falling back to Podman. Set <code>CONTAINER_RUNTIME=podman</code> to explicitly select Podman. Each script reports the selected container runtime on stderr before doing any build work. Docker Hub image references are fully qualified, so Podman does not require short-name aliases or an unqualified-search registry configuration.</p><p>For access to the default JFrog images and shared dependency cache, create <code>.env</code> in the HPCC-Platform repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JFROG_USERNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your.name@example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JFROG_PASSWORD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;your-password-or-PAT&#39;</span></span></code></pre></div><p>Keep credentials out of version control. The file is optional if the required images are already available locally. Set <code>ENV_FILE</code> to use another file.</p><p>The build automatically pulls the builder image, reuses a local image if the pull fails, or builds one if needed. The first build can take longer while dependencies are downloaded and compiled.</p><p>APK builds require unprivileged user namespaces. The script checks this before building and reports any required host configuration.</p><h2 id="common-build-options" tabindex="-1">Common Build Options <a class="header-anchor" href="#common-build-options" aria-label="Permalink to &quot;Common Build Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--glibc &lt;version&gt;</code></td><td>Change the glibc baseline; GCC follows the baseline unless overridden.</td></tr><tr><td><code>--gcc &lt;major&gt;</code></td><td>Override the GCC version.</td></tr><tr><td><code>--arch amd64</code> or <code>--arch arm64</code></td><td>Select the architecture; defaults to the host.</td></tr><tr><td><code>-f deb,rpm</code></td><td>Build only the listed formats instead of all three.</td></tr><tr><td><code>-b &lt;directory&gt;</code></td><td>Change the build directory.</td></tr><tr><td><code>-o &lt;directory&gt;</code></td><td>Write packages and SBOMs to a separate directory.</td></tr><tr><td><code>--containerized</code></td><td>Build for Kubernetes rather than host installation.</td></tr><tr><td><code>--no-pull</code></td><td>Reuse or build a local builder image without pulling it.</td></tr><tr><td><code>--help</code></td><td>Show all options.</td></tr></tbody></table><p>For example, build DEB and RPM packages with glibc 2.39 and its paired GCC 13:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/build.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --glibc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.39</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deb,rpm</span></span></code></pre></div><p>Each baseline and architecture gets a separate default build directory. Kubernetes builds also add <code>-containerized</code> to the directory name. If you use <code>-b</code>, keep separate directories for different toolchains and build modes.</p><p>The default glibc 2.34 baseline targets Ubuntu 21.10 or later, Rocky 9 or later, and Wolfi. Rocky 8 is not supported. Newer baselines require newer target libraries.</p><h2 id="run-cmake-directly" tabindex="-1">Run CMake Directly <a class="header-anchor" href="#run-cmake-directly" aria-label="Permalink to &quot;Run CMake Directly&quot;">​</a></h2><p>Use <a href="./cmake-chainguard.sh.html">cmake-chainguard.sh</a> to run a CMake command inside the builder with the same arguments:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/cmake-chainguard.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>It defaults to glibc 2.34 and GCC 11. Set <code>CHAINGUARD_GLIBC</code> and <code>CHAINGUARD_GCC</code> to override them.</p><p>The proxy runs only the requested CMake command. It does not supply HPCC&#39;s configure flags, build automatically, or create packages. Use <a href="./build.sh.html">build.sh</a> for the complete HPCC build.</p><h2 id="build-a-development-image" tabindex="-1">Build a Development Image <a class="header-anchor" href="#build-a-development-image" aria-label="Permalink to &quot;Build a Development Image&quot;">​</a></h2><p>The build script handles this automatically. To prepare the default image separately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/create-build-image.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --glibc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.34</span></span></code></pre></div><p>Run <a href="./create-build-image.sh.html">create-build-image.sh</a> with <code>--help</code> for options.</p><h2 id="ci-image-freshness" tabindex="-1">CI Image Freshness <a class="header-anchor" href="#ci-image-freshness" aria-label="Permalink to &quot;CI Image Freshness&quot;">​</a></h2><p>LN&#39;s default Chainguard CI build rebuilds its selected development image on every run using <code>create-build-image.sh --rebuild</code>. The development-image publishing workflow uses the same option. It bypasses both published/local image reuse and Docker&#39;s layer cache, and pulls the current base-image tags. Toolchain builds refresh the Ubuntu sysroot packages and upgrade Wolfi packages without changing the selected glibc baseline or GCC major.</p><p>An explicitly supplied builder image is pulled before use; pull failures stop the build rather than silently reusing an old local image. <code>--no-pull</code> explicitly opts out, including when CI needs to use its freshly rebuilt local builder. Packaging layers are rebuilt without cache and upgrade installed Wolfi packages. They deliberately use the selected local base instead of pulling it a second time, which would replace CI&#39;s newly rebuilt builder with the published one. For sysroot builders, packaging layers also reapply the toolchain&#39;s <code>include-fixed</code> cleanup after APK operations so GCC updates cannot restore Wolfi glibc headers that take precedence over the selected sysroot.</p><p>CI pulls runtime bases and disables layer reuse for both the runtime audit and the published runtime image. The isolated runtime rootfs installs current APK packages, and the R-package build stage upgrades its installed packages. The distroless JDK/FIPS runtime has no package manager: its inherited packages are refreshed by pulling the current configured upstream image. Explicit version constraints (including Python/GCC compatibility, Mono, NuGet, and syft) remain in place; unsupported upstream images cannot acquire updates no longer published.</p><p>For local development, <code>create-build-image.sh --no-pull</code> still reuses an existing image. Use <code>--rebuild</code> to force a fresh one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/create-build-image.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --glibc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.34</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rebuild</span></span></code></pre></div><p>The image-selection regression tests run without a container engine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dockerfiles/chainguard/tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h2 id="runtime-image-audit" tabindex="-1">Runtime Image Audit <a class="header-anchor" href="#runtime-image-audit" aria-label="Permalink to &quot;Runtime Image Audit&quot;">​</a></h2><p>The <code>runtime-audit</code> target in <a href="./containers/Dockerfile.runtime.html">Dockerfile.runtime</a> checks the assembled runtime before the final image can be built. Its Python check uses the native HPCC compiler, <code>eclcc -Me</code>, to evaluate a foldable <code>EMBED(Python3)</code> function inside the <code>runtime-python-audit</code> stage, derived from <code>runtime</code> with its user, working directory and environment. Docker supplies <code>/proc</code> in this stage; HPCC needs <code>/proc/self/exe</code> to discover its plugin path, so this check must not run in a bare copied-root <code>chroot</code>. The function reads <code>sys.version_info</code>; its result must match <code>RUNTIME_PYTHON</code>, which must also match <code>PYTHON</code> in the packaged <code>hpcc-baseline</code>. Missing libraries, plugin initialization/evaluation failures, and version mismatches fail the audit rather than bypassing it.</p><p>The <code>runtime-audit</code> target retains the filesystem, dependency and SBOM checks and requires the Python-stage success marker. The final image in turn requires the <code>runtime-audit</code> success marker, so neither audit can be skipped.</p><p>Do not test <code>libpy3embed.so</code> with Python&#39;s <code>ctypes.CDLL</code>. This is an HPCC embedding plugin, not a Python extension: its global initialization initializes the interpreter and releases the GIL with <code>PyEval_SaveThread</code>. Loading it from an already-running Python interpreter interferes with that host&#39;s interpreter and thread state. The previous <code>ctypes</code> audit segfaulted (exit 139) with Python 3.12; that failure alone does not establish a packaging or ABI defect. Native ECL evaluation exercises the supported embedding path instead. This smoke check does not replace the Python embedding regression suite or prove that every distributed query works.</p><h2 id="ln-builds" tabindex="-1">LN Builds <a class="header-anchor" href="#ln-builds" aria-label="Permalink to &quot;LN Builds&quot;">​</a></h2><p>To build LN, run its wrapper from the LN repository root instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dockerfiles/chainguard/build.sh</span></span></code></pre></div><p>The wrapper uses the sibling HPCC-Platform checkout for tooling, reads LN&#39;s <code>.env</code>, and writes to <code>../build/chainguard-glibc2.34-gcc11/</code>. Use <code>-s /path/to/HPCC-Platform</code> to select another checkout.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Image</th><th>Sysroot</th><th style="text-align:right;">GCC</th><th><code>GLIBC</code> / <code>GLIBCXX</code></th><th style="text-align:right;">Python</th><th>Supported targets</th></tr></thead><tbody><tr><td><code>hpcc-chainguard-glibc2.34-gcc11-dev</code></td><td>Ubuntu 21.10</td><td style="text-align:right;">11</td><td>2.34 / 3.4.29</td><td style="text-align:right;">3.9</td><td>Ubuntu &gt;= 21.10, Rocky &gt;= 9, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.35-gcc11-dev</code></td><td>Ubuntu 22.04</td><td style="text-align:right;">11</td><td>2.35 / 3.4.30</td><td style="text-align:right;">3.10</td><td>Ubuntu &gt;= 22.04, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.36-gcc11-dev</code></td><td>Ubuntu 22.10</td><td style="text-align:right;">11</td><td>2.36 / 3.4.30</td><td style="text-align:right;">3.10</td><td>Ubuntu &gt;= 22.10, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.37-gcc11-dev</code></td><td>Ubuntu 23.04</td><td style="text-align:right;">11</td><td>2.37 / 3.4.32</td><td style="text-align:right;">3.11</td><td>Ubuntu &gt;= 23.04, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.38-gcc13-dev</code></td><td>Ubuntu 23.10</td><td style="text-align:right;">13</td><td>2.38 / 3.4.32</td><td style="text-align:right;">3.11</td><td>Ubuntu &gt;= 23.10, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.39-gcc13-dev</code></td><td>Ubuntu 24.04</td><td style="text-align:right;">13</td><td>2.39 / 3.4.33</td><td style="text-align:right;">3.12</td><td>Ubuntu &gt;= 24.04, Rocky &gt;= 10, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.40-gcc13-dev</code></td><td>Ubuntu 24.10</td><td style="text-align:right;">13</td><td>2.40 / 3.4.33</td><td style="text-align:right;">3.12</td><td>Ubuntu &gt;= 24.10, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.41-gcc13-dev</code></td><td>Ubuntu 25.04</td><td style="text-align:right;">13</td><td>2.41 / 3.4.34</td><td style="text-align:right;">3.13</td><td>Ubuntu &gt;= 25.04, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.42-gcc15-dev</code></td><td>Ubuntu 25.10</td><td style="text-align:right;">15</td><td>2.42 / 3.4.34</td><td style="text-align:right;">3.13</td><td>Ubuntu &gt;= 25.10, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.43-gcc15-dev</code></td><td>Ubuntu 26.04</td><td style="text-align:right;">15</td><td>2.43 / 3.4.35</td><td style="text-align:right;">3.14</td><td>Ubuntu &gt;= 26.04, Wolfi</td></tr><tr><td><code>hpcc-chainguard-glibc2.44-gcc16-dev</code></td><td>Ubuntu 26.10</td><td style="text-align:right;">16</td><td>2.44 / 3.4.36</td><td style="text-align:right;">3.14</td><td>Ubuntu &gt;= 26.10, Wolfi</td></tr></tbody></table>`,48)])])}const g=t(d,[["render",n]]);export{p as __pageData,g as default};
